ws = websocket.create_connection(alvo['webSocketDebuggerUrl'], timeout=60)

expr = r"""
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  for (let i = 0; i < 40 && !window.angular; i++) await sleep(250);
  const el = document.querySelector('[ng-view]');
  if (!el || !window.angular) return {erro: 'angular nao carregou'};
  for (let i = 0; i < 40; i++) {
    const s = angular.element(el).scope();
    if (s && s.Sequencia && s.Sequencia.sequenciasFamosas.length) break;
    await sleep(250);
  }
  const scope = angular.element(el).scope();
  const vm = scope.Sequencia;
  vm.limparPesquisa();
  ['C#', 'G'].forEach(a => { vm.acordeInput = a; vm.adicionarAcorde(); });
  scope.$apply();
  vm.cadastrarSequencia();
  scope.$apply();
  await sleep(5000);
  const recursos = performance.getEntriesByType('resource')
    .map(e => e.name).filter(n => n.indexOf('similares') !== -1);
  return {
    selecionada: (vm.minhaSequencia.acordes || []).map(a => a.acorde).join(','),
    musicas: vm.musics.length,
    speech: vm.esfigeSpeech,
    mensagem: vm.mensagemCadastro,
    requisicoes: recursos.slice(-3)
  };
})()
"""

ws.send(json.dumps({'id': 1, 'method': 'Runtime.evaluate',
