import json, urllib.request, base64, sys
import websocket

alvos = json.load(urllib.request.urlopen('http://localhost:9222/json'))
alvo = [a for a in alvos if a['type'] == 'page'][0]
ws = websocket.create_connection(alvo['webSocketDebuggerUrl'], timeout=60)
_id = [0]

def cmd(method, **params):
    _id[0] += 1
    ws.send(json.dumps({'id': _id[0], 'method': method, 'params': params}))
    while True:
        m = json.loads(ws.recv())
        if m.get('id') == _id[0]:
            return m

def js(expr, await_promise=False):
    r = cmd('Runtime.evaluate', expression=expr, awaitPromise=await_promise,
            returnByValue=True)
    return r['result']['result'].get('value')

js("""
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  for (let i = 0; i < 60 && !document.querySelector('.form-control-solto'); i++) await sleep(250);
  return !!document.querySelector('.form-control-solto');
})()
""", True)

expr = r"""
(() => {
  const input = document.querySelector('.form-control-solto');
  if (!input) return {erro: 'input nao encontrado'};

  const lum = c => {
    const [r, g, b] = c.match(/[\d.]+/g).slice(0, 3).map(Number).map(v => {
      v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const ratio = (a, b) => {
    const l1 = lum(a), l2 = lum(b);
    return ((Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05)).toFixed(2);
  };
  const alpha = c => { const p = c.match(/[\d.]+/g).map(Number); return p.length > 3 ? p[3] : 1; };
  const compor = (frente, fundo) => {
    const f = frente.match(/[\d.]+/g).map(Number), b = fundo.match(/[\d.]+/g).map(Number);
    const a = f.length > 3 ? f[3] : 1;
    return 'rgb(' + [0,1,2].map(i => Math.round(f[i]*a + b[i]*(1-a))).join(',') + ')';
  };
  const fundoDe = el => {
    let n = el;
    while (n && n !== document.documentElement) {
      const bg = getComputedStyle(n).backgroundColor;
      if (alpha(bg) > 0.99) return bg;
      n = n.parentElement;
    }
    return getComputedStyle(document.body).backgroundColor;
  };

  const painel = fundoDe(input);
  const medir = rotulo => {
    const s = getComputedStyle(input);
    const bg = s.backgroundColor === 'rgba(0, 0, 0, 0)' ? painel : compor(s.backgroundColor, painel);
    return {
      estado: rotulo,
      color: s.color,
      backgroundColor: s.backgroundColor,
      fundo_efetivo: bg,
      border: s.borderTopWidth + ' ' + s.borderTopColor,
      contraste_texto: ratio(s.color, bg),
      contraste_placeholder: ratio(getComputedStyle(input, '::placeholder').color, bg)
    };
  };

  input.blur();
  const normal = medir('normal');
  input.focus();
  const foco = medir(':focus');

  // texto digitado de fato aparece?
  input.value = 'C#7M/9';
  input.dispatchEvent(new Event('input', {bubbles: true}));
  const comTexto = medir('com texto');

  return {
    visivel: !!(input.offsetWidth && input.offsetHeight),
    rect: input.getBoundingClientRect().toJSON(),
    classe: input.className,
    painel,
    normal, foco, comTexto
  };
})()
"""
