            return m

def js(expr, await_promise=False):
    r = cmd('Runtime.evaluate', expression=expr, awaitPromise=await_promise, returnByValue=True)
    return r['result']['result'].get('value')

# input limpo, focado, com texto
js("""(() => {
  const el = document.querySelector('[ng-view]');
  const vm = angular.element(el).scope().Sequencia;
  vm.limparPesquisa(); angular.element(el).scope().$apply();
