# quantos pixels claros (texto) existem
claros = sum(n for c, n in cores.items() if lum(c) > 0.7)
print('pixels de texto (luminância > 0.7):', claros)
print('OK' if claros > 100 and contraste(mais_claro, fundo) > 4.5 else 'FALHOU')
